208	/**
209	 * Get the sign of a single data.
210	 *
211	 * @returns 0 for doji with hasDojiColor: true,
212	 *          1 for positive,
213	 *          -1 for negative.
214	 */
215	function getSign(
216	    store: DataStore, dataIndex: number, openVal: number, closeVal: number, closeDimI: DimensionIndex,
217	    hasDojiColor: boolean
218	): -1 | 1 | 0 {
219	    let sign: -1 | 1 | 0;
220	    if (openVal > closeVal) {
221	        sign = -1;
222	    }
223	    else if (openVal < closeVal) {
224	        sign = 1;
225	    }
226	    else {
227	        sign = hasDojiColor
228	            // When doji color is set, use it instead of color/color0.
229	            ? 0
230	            : (dataIndex > 0
231	                // If close === open, compare with close of last record
232	                ? (store.get(closeDimI, dataIndex - 1) <= closeVal ? 1 : -1)
233	                // No record of previous, set to be positive
234	                : 1
235	            );
236	    }
237	
238	    return sign;
239	}
