207	    function layEndLine(ends: number[][], endCenter: number[]) {
208	        const from = endCenter.slice();
209	        const to = endCenter.slice();
210	        from[cDimIdx] -= halfWidth;
211	        to[cDimIdx] += halfWidth;
212	        ends.push(from, to);
213	    }
