interface CommonOption extends SeriesOption, SeriesOnCartesianOptionMixin {
    // - 'horizontal': Multiple whisker boxes (each drawn vertically)
    //      are arranged side by side horizontally.
    // - 'vertical': The opposite.
    layout?: LayoutOrient

