import { EChartsType } from '@/src/echarts';
import { createChart } from '../../test/ut/core/utHelper';
import { CandlestickItemLayout } from '@/src/chart/candlestick/candlestickLayout';

describe('candlestick_series_encode_render', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    // [date, open, close, low, high]
    const daval = [
        ['2017-10-24', 20, 34, 10, 38],
        ['2017-10-25', 40, 35, 30, 50],
        ['2017-10-26', 31, 38, 33, 44],
        ['2017-10-27', 38, 15, 5, 42]
    ];

    function getLayout(dataIndex: number): CandlestickItemLayout {
        const seriesModel = chart.getModel().getSeriesByIndex(0) as any;
        return seriesModel.getData().getItemLayout(dataIndex) as CandlestickItemLayout;
    }

    function expectAllFinite(layout: CandlestickItemLayout) {
        layout.ends.forEach(function (pt) {
            expect(isFinite(pt[0])).toEqual(true);
            expect(isFinite(pt[1])).toEqual(true);
        });
        expect(isFinite(layout.initBaseline)).toEqual(true);
    }

    it('horizontal layout (x category) with encode', function () {
        chart.setOption({
            xAxis: { type: 'category' },
            yAxis: { type: 'value' },
            series: [{
                type: 'candlestick',
                encode: { x: 0, y: [1, 2, 3, 4] },
                data: daval
            }]
        });

        const layout = getLayout(0); // open 20, close 34, low 10, high 38
        expectAllFinite(layout);
        expect(layout.sign).toEqual(1); // close > open
        const ends = layout.ends;
        // Whisker (highest->ocHigh, lowest->ocLow) is vertical: same x.
        expect(ends[4][0]).toEqual(ends[5][0]);
        expect(ends[6][0]).toEqual(ends[7][0]);
        // Screen y grows downward: highest <= ocHigh <= ocLow <= lowest.
        expect(ends[4][1]).toBeLessThanOrEqual(ends[5][1]);
        expect(ends[5][1]).toBeLessThanOrEqual(ends[7][1]);
        expect(ends[7][1]).toBeLessThanOrEqual(ends[6][1]);
        // Body corners share the same center x.
        expect(ends[0][0]).toBeLessThan(ends[1][0]); // body has width along x
    });

    it('vertical layout (y category) with encode', function () {
        chart.setOption({
            xAxis: { type: 'value' },
            yAxis: { type: 'category' },
            series: [{
                type: 'candlestick',
                encode: { x: [1, 2, 3, 4], y: 0 },
                data: daval
            }]
        });

        const layout = getLayout(0);
        expectAllFinite(layout);
        expect(layout.sign).toEqual(1);
        const ends = layout.ends;
        // Whisker is horizontal: same y.
        expect(ends[4][1]).toEqual(ends[5][1]);
        expect(ends[6][1]).toEqual(ends[7][1]);
        // Screen x grows rightward: lowest <= ocLow <= ocHigh <= highest.
        expect(ends[6][0]).toBeLessThanOrEqual(ends[7][0]);
        expect(ends[7][0]).toBeLessThanOrEqual(ends[5][0]);
        expect(ends[5][0]).toBeLessThanOrEqual(ends[4][0]);
        // Body has width along y.
        expect(ends[0][1]).toBeLessThan(ends[1][1]);
    });

    it('time axis with swapped open/close/low/high encode mapping', function () {
        chart.setOption({
            xAxis: { type: 'time' },
            yAxis: { type: 'value' },
            series: [{
                type: 'candlestick',
                // open=1, close=3, low=2, high=4 (swapped close/low)
                encode: { x: 0, y: [1, 3, 2, 4] },
                data: daval
            }]
        });

        // open 20, close 10 -> negative sign; low 34, high 38.
        const layout = getLayout(0);
        expectAllFinite(layout);
        expect(layout.sign).toEqual(-1);
        const ends = layout.ends;
        // Whisker vertical: same x.
        expect(ends[4][0]).toEqual(ends[5][0]);
        // highest (38) above ocHigh (max(20,10)=20) above lowest (34)? low 34 > close 10,
        // so lowest is below ocLow on screen.
        expect(ends[4][1]).toBeLessThanOrEqual(ends[5][1]);
        expect(ends[7][1]).toBeLessThanOrEqual(ends[6][1]);
    });

    it('yAxis time implies vertical layout with encode', function () {
        chart.setOption({
            xAxis: { type: 'value' },
            yAxis: { type: 'time' },
            series: [{
                type: 'candlestick',
                encode: { x: [1, 2, 3, 4], y: 0 },
                data: daval
            }]
        });

        const layout = getLayout(0);
        expectAllFinite(layout);
        const ends = layout.ends;
        // Vertical layout: whisker horizontal (same y).
        expect(ends[4][1]).toEqual(ends[5][1]);
        expect(ends[6][1]).toEqual(ends[7][1]);
    });

    it('boxplot vertical layout (y category) with encode still works', function () {
        chart.setOption({
            xAxis: { type: 'value' },
            yAxis: { type: 'category' },
            series: [{
                type: 'boxplot',
                encode: { x: [1, 2, 3, 4, 5], y: 0 },
                data: [
                    ['a', 10, 20, 30, 40, 50],
                    ['b', 15, 25, 35, 45, 55]
                ]
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as any;
        const layout = seriesModel.getData().getItemLayout(0);
        layout.ends.forEach(function (pt: number[]) {
            expect(isFinite(pt[0])).toEqual(true);
            expect(isFinite(pt[1])).toEqual(true);
        });
    });
});

